def _build_catalog() -> list[dict[str, Any]]:
    catalog: list[dict[str, Any]] = list(_BASELINE_TOOLKITS)
    for key, name, category, description, modules, auth_schemes in _ECOSYSTEM_SEEDS:
        m0 = modules[0] if modules else "General"
        m1 = modules[1] if len(modules) > 1 else m0
        m2 = modules[2] if len(modules) > 2 else m0

        tools = [
            {
                "name": f"{key}_query",
                "action": f"{key.upper()}_QUERY",
                "module": m0,
                "description": f"Search and inspect records in {name} ({m0}).",
                "risk": "low",
                "connector": "composio",
                "secret_ref": f"{key}:{key}_query",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "query": {"type": "string", "description": f"Search query for {name}"},
                        "limit": {"type": "integer", "description": "Maximum records to return"},
                    },
                    "required": [],
                },
            },
            {
                "name": f"{key}_execute",
                "action": f"{key.upper()}_EXECUTE",
                "module": m1,
                "description": f"Execute operations and create records in {name} ({m1}).",
                "risk": "medium",
                "connector": "composio",
                "secret_ref": f"{key}:{key}_execute",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "action": {"type": "string", "description": "Operation name"},
                        "payload": {"type": "object", "description": f"Payload attributes for {name}"},
                    },
                    "required": ["payload"],
                },
            },
            {
                "name": f"{key}_sync",
                "action": f"{key.upper()}_SYNC",
                "module": m2,
                "description": f"Synchronize and update resources in {name} ({m2}).",
                "risk": "medium",
                "connector": "composio",
                "secret_ref": f"{key}:{key}_sync",
                "input_schema": {
                    "type": "object",
                    "properties": {
                        "id": {"type": "string", "description": "Resource identifier"},
                        "properties": {"type": "object", "description": "Fields to update"},
                    },
                    "required": ["id"],
                },
            },
        ]

        catalog.append({
            "key": key,
            "name": name,
            "category": category,
            "provider": "composio",
            "description": description,
            "composio_app": key.upper(),
            "auth_schemes": auth_schemes,
            "docs_url": f"https://composio.dev/tools/{key}",
            "default_action": f"{key.upper()}_EXECUTE",
            "modules": modules,
            "tools": tools,
        })
    return catalog


# The full 1,640 Composio toolkits catalog
COMPOSIO_TOOLKITS_1640: list[dict[str, Any]] = _build_catalog()

# Primary key index for O(1) lookups
_KEY_TO_TOOLKIT: dict[str, dict[str, Any]] = {t["key"]: t for t in COMPOSIO_TOOLKITS_1640}


def get_composio_toolkits(
    category: str | None = None,
    search: str | None = None,
    limit: int = 100,
    offset: int = 0,
) -> tuple[list[dict[str, Any]], int]:
    """Filter and paginate Composio toolkits with live search."""
    items = COMPOSIO_TOOLKITS_1640

    if category and category.strip().lower() != "all":
        cat_lower = category.strip().lower()
        items = [t for t in items if t["category"].lower() == cat_lower]

    if search and search.strip():
        q = search.strip().lower()
        items = [
            t for t in items
            if q in t["key"].lower()
            or q in t["name"].lower()
            or q in t["description"].lower()
            or any(q in m.lower() for m in t.get("modules", []))
            or q in t["category"].lower()
        ]

    total_count = len(items)

    if limit is None or limit <= 0:
        page_items = items[offset:]
    else:
        page_items = items[offset : offset + limit]

    return page_items, total_count


def get_composio_toolkit_by_key(key: str) -> dict[str, Any] | None:
    """Retrieve a single toolkit by key with O(1) lookup."""
    if not key:
        return None
    return _KEY_TO_TOOLKIT.get(key.strip().lower())


def get_toolkit_categories() -> list[dict[str, Any]]:
    """Return category distribution across all toolkits."""
    counts: dict[str, int] = {}
    for t in COMPOSIO_TOOLKITS_1640:
        cat = t["category"]
        counts[cat] = counts.get(cat, 0) + 1
    return [{"name": cat, "count": count} for cat, count in counts.items()]
